// Generated by scripts/generate-responsive-images.mjs — widths are the intrinsic sizes of public/blog/*.webp.
export const contentImageSize = {
  "/blog/agents.webp": { width: 1536, height: 1024 },
  "/blog/ai-agent-custom-system-cost.webp": { width: 1600, height: 900 },
  "/blog/ai-automation-start.webp": { width: 1536, height: 1024 },
  "/blog/ai-lead-agent.webp": { width: 1536, height: 1024 },
  "/blog/apps-ai.webp": { width: 1536, height: 1024 },
  "/blog/chatbot-vs-agent.webp": { width: 1600, height: 900 },
  "/blog/crm-custom-fit.webp": { width: 1600, height: 900 },
  "/blog/custom.webp": { width: 1536, height: 1024 },
  "/blog/inquiry-management.webp": { width: 1600, height: 900 },
  "/blog/landing-vs-inquiry-system.webp": { width: 1600, height: 900 },
  "/blog/no-answer-lead-follow-up.webp": { width: 1600, height: 900 },
  "/blog/products.webp": { width: 1536, height: 1024 },
  "/blog/sales-follow-up-phone-whatsapp.webp": { width: 1600, height: 900 },
  "/blog/site-crm-whatsapp-automation.webp": { width: 1600, height: 900 },
  "/blog/voice-ai-phone-agent.webp": { width: 1600, height: 900 },
  "/blog/whatsapp-ai-agent.webp": { width: 1600, height: 900 },
} as const;

export type ContentImageSrc = keyof typeof contentImageSize;

export const contentImageVariantWidths = [640, 960, 1280] as const;

export function contentImageSrcSet(src: string) {
  const size = contentImageSize[src as ContentImageSrc];
  if (!size) return undefined;
  const stem = src.replace(/\.webp$/, "");
  const parts = contentImageVariantWidths
    .filter((width) => width < size.width)
    .map((width) => `${stem}-${width}.webp ${width}w`);
  parts.push(`${src} ${size.width}w`);
  return parts.join(", ");
}
